  assert.equal(videoScriptStatusLabel("packaging"), "Publishing…");
  assert.equal(videoScriptLanguageLabel("hi"), "Hindi");
  assert.equal(videoScriptLanguageLabel("en"), "English");
  assert.equal(videoScriptLanguageLabel("fr"), "fr");
});

