cat > ./.db-check.ts <<'EOF'
import "dotenv/config";
import { prisma } from "@/db";
import { listVideoScriptsForUser } from "@/services/videoScript/videoScriptList";
import { getTrendingNewsStories } from "@/services/news/trendingNewsStoriesService";

void (async () => {
  const users = await prisma.videoScript.groupBy({ by: ["userId"], _count: { _all: true } });
  console.log("script rows per user:", users.map((u) => u._count._all));
  for (const u of users) {
    const items = await listVideoScriptsForUser(u.userId);
    const stories = await prisma.videoScript.findMany({ where: { userId: u.userId }, distinct: ["newsId"], select: { newsId: true } });
    const ids = new Set(items.map((i) => i.storyId));
    const sorted = items.every((i, n) => n === 0 || items[n - 1].createdAt >= i.createdAt);
    // the card must be the same row the script page shows (latest per story)
    let sameAsPage = true;
    for (const item of items) {
      const latest = await prisma.videoScript.findFirst({ where: { newsId: item.storyId, userId: u.userId }, orderBy: { createdAt: "desc" }, select: { id: true } });
      if (latest?.id !== item.id) sameAsPage = false;
    }
    console.log({ cards: items.length, distinctStories: stories.length, uniqueCards: ids.size === items.length, newestFirst: sorted, matchesScriptPage: sameAsPage });
    console.log(items.slice(0, 2).map(({ statusLabel, scriptTitle, hook, durationSec, beatCount, storyImageUrl, href }) => ({ statusLabel, scriptTitle, hook: hook?.slice(0, 50), durationSec, beatCount, img: Boolean(storyImageUrl), href })));
  }
  const trending = await getTrendingNewsStories();
  console.log("trending:", trending.length, trending.map((s) => [s.upvotes, s.title.slice(0, 40)]));
  await prisma.$disconnect();
})();
EOF
