// Usage: node shoot.mjs <outDir> <width> <path...>
// Phone-width screenshots (scrolling the app's inner scroll container) plus a
// report of elements that overflow the viewport horizontally.
import { chromium } from "playwright-core";

const [outDir, widthArg, ...paths] = process.argv.slice(2);
const width = Number(widthArg) || 390;
const base = process.env.BASE ?? "http://localhost:3100";

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome" });
const context = await browser.newContext({
  viewport: { width, height: 844 },
  deviceScaleFactor: 1,
  isMobile: true,
  hasTouch: true,
});

for (const path of paths) {
  const page = await context.newPage();
  const slug = path.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "root";
  try {
    await page.goto(base + path, { waitUntil: "networkidle", timeout: 60000 });
  } catch {
    // keep going with whatever rendered
  }
  await page.waitForTimeout(1500);

  const report = await page.evaluate((vw) => {
    const offenders = [];
    for (const el of document.querySelectorAll("body *")) {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;
      if (r.right > vw + 1 || r.left < -1) {
        const style = getComputedStyle(el);
        if (style.position === "fixed" && style.visibility === "hidden") continue;
        offenders.push(
          `${el.tagName.toLowerCase()}.${String(el.className).slice(0, 90)} [${Math.round(r.left)}→${Math.round(r.right)}] "${(el.textContent ?? "").trim().slice(0, 40)}"`,
        );
      }
    }
    const scrollers = [...document.querySelectorAll("*")]
      .filter((el) => {
        const s = getComputedStyle(el);
        return /(auto|scroll)/.test(s.overflowY) && el.scrollHeight > el.clientHeight + 40;
      })
      .sort((a, b) => b.scrollHeight - a.scrollHeight);
    const main = scrollers[0];
    if (main) main.setAttribute("data-shot-scroller", "1");
    return {
      docScrollWidth: document.documentElement.scrollWidth,
      offenders: offenders.slice(0, 25),
      scrollHeight: main ? main.scrollHeight : document.documentElement.scrollHeight,
      clientHeight: main ? main.clientHeight : 844,
    };
  }, width);

  console.log(`\n== ${path}  docScrollWidth=${report.docScrollWidth} contentHeight=${report.scrollHeight}`);
  for (const line of report.offenders) console.log("  overflow:", line);

  const steps = Math.min(6, Math.ceil(report.scrollHeight / report.clientHeight));
  for (let i = 0; i < steps; i += 1) {
    await page.evaluate(
      ([i, h]) => {
        const el = document.querySelector("[data-shot-scroller]");
        if (el) el.scrollTop = i * h;
        else window.scrollTo(0, i * h);
      },
      [i, report.clientHeight - 60],
    );
    await page.waitForTimeout(400);
    await page.screenshot({ path: `${outDir}/${slug}_${i}.png` });
  }
  await page.close();
}
await browser.close();

