import re,subprocess
files=subprocess.check_output(["bash","-c",r"grep -rlE '\b(py|pt|pb|mt|mb|gap|space-y)-(16|20|24|28|32|36|40)\b' --include=*.tsx components app"]).decode().split()
half={'16':'8','20':'10','24':'12','28':'14','32':'16','36':'16','40':'20'}
pat=re.compile(r'(?<=[\s"\'`])(py|pt|pb|mt|mb|gap|space-y)-(16|20|24|28|32|36|40)(?=[\s"\'`])')
total=0
for f in files:
    lines=open(f).read().split('\n')
    changed=0
    for i,l in enumerate(lines):
        def rep(m):
            nonlocal_l=lines[i]
            if f"max-sm:{m.group(1)}-" in nonlocal_l: return m.group(0)
            return f"{m.group(0)} max-sm:{m.group(1)}-{half[m.group(2)]}"
        new=pat.sub(rep,l)
        if new!=l:
            lines[i]=new; changed+=1
    if changed:
        open(f,'w').write('\n'.join(lines)); total+=changed
        print(changed,f)
print('lines',total)
EOF
